func modelIDFromValue(raw any) string {
	switch v := raw.(type) {
	case string:
		return strings.TrimSpace(v)
	case map[string]any:
		for _, key := range []string{"id", "name", "model", "model_id"} {
			if value, ok := v[key].(string); ok && strings.TrimSpace(value) != "" {
				return strings.TrimSpace(value)
			}
